// 24h-window digest. Independent state from urgent-relay — we pull the last 24h of
// chris-bot posts and summarize the FYI ones (no @kyle-bot mention).
const nowMs = Date.now();
const sinceMs = nowMs - 24 * 60 * 60 * 1000;
return [{ json: {
  sinceMs,
  nowMs,
  channelId: 'qoia7dfowb8q9n16ukkidb874c',
  chrisBotUserId: 'b5jiw3sk13rbibcbt4t98gf1ra',
  dmChannelId: 'cqhn533i8tnszryak11ysnkj3r',
  mattermostBase: 'https://chat.birdmug.com/api/v4',
  ollamaUrl: 'http://100.83.51.117:11434/api/generate',
  ollamaModel: 'qwen2.5:7b'
} }];

// Collect FYI chris-bot posts (no @kyle-bot mention, non-system) into a digestable blob.
const ctx = $('Compute Window').first().json;
const apiResp = $json;

if (apiResp && apiResp.error) {
  throw new Error('Mattermost API error fetching 24h posts: ' + JSON.stringify(apiResp.error));
}
if (!apiResp || !('order' in apiResp) || !('posts' in apiResp)) {
  throw new Error('Mattermost response missing expected keys (got ' + Object.keys(apiResp || {}).join(',') + ')');
}

const order = Array.isArray(apiResp.order) ? apiResp.order : [];
const posts = apiResp.posts || {};
const chronological = [...order].reverse();

const fyi = [];
for (const pid of chronological) {
  const p = posts[pid];
  if (!p) continue;
  if (p.user_id !== ctx.chrisBotUserId) continue;
  if (p.type && p.type !== '') continue;
  const msg = (p.message || '').toString();
  if (msg.includes('@kyle-bot')) continue; // urgent posts already went via urgent-relay
  fyi.push({
    create_at: p.create_at,
    iso: new Date(p.create_at).toISOString().slice(0, 16).replace('T', ' '),
    message: msg
  });
}

// If no FYI traffic at all, skip the entire downstream — return empty
if (fyi.length === 0) {
  return [];
}

const joined = fyi.map(f => `[${f.iso} UTC]\n${f.message}`).join('\n\n---\n\n');
const prompt = `You summarize one day of FYI / status posts from "chris-bot" (an AI assistant Chris uses) into a brief digest for Kyle. The posts below are NOT directed asks — those went through a separate urgent-relay. These are status updates, FYIs, broadcasts.

Rules:
- 2-4 short sentences, plain prose, no markdown headers, no bullet lists.
- Lead with the most actionable or surprising item.
- If the posts are mundane (no signal), say so in one sentence.
- Don't hallucinate — only summarize what's actually in the posts.
- No sign-off, no "hope this helps," terse.

Posts (${fyi.length} total in last 24h):

${joined}

Summary:`;

return [{ json: {
  prompt,
  fyiCount: fyi.length,
  oldestIso: fyi[0].iso,
  newestIso: fyi[fyi.length - 1].iso,
  ollamaUrl: ctx.ollamaUrl,
  ollamaModel: ctx.ollamaModel,
  mattermostBase: ctx.mattermostBase,
  dmChannelId: ctx.dmChannelId
} }];

// Combine narrative + raw count, fall back to static if Ollama unreachable.
const prior = $('Build Digest Prompt').first().json;
const ollamaOut = $json;
const narrative = (ollamaOut && typeof ollamaOut.response === 'string' && ollamaOut.response.trim())
  ? ollamaOut.response.trim()
  : null;
const ollamaFailed = !narrative;

let text;
if (narrative) {
  text = `:scroll: **chris-bot 24h digest** (${prior.fyiCount} FYI post${prior.fyiCount === 1 ? '' : 's'}, ${prior.oldestIso}–${prior.newestIso} UTC)\n\n${narrative}\n\nDirected asks went via urgent-relay DMs in the same window.`;
} else {
  text = `:scroll: **chris-bot 24h digest** (${prior.fyiCount} FYI post${prior.fyiCount === 1 ? '' : 's'}, ${prior.oldestIso}–${prior.newestIso} UTC)\n\n_Ollama at Kaydanski was unreachable — count only, no narrative._\n\nRun \`botchat read --all\` from any host to see the underlying posts.`;
}

return [{ json: {
  text,
  ollamaOk: !ollamaFailed,
  mattermostBase: prior.mattermostBase,
  dmChannelId: prior.dmChannelId
} }];
